mapper.select:
SELECT id
FROM wallets
WHERE child_id = #{childId}

SELECT IFNULL(SUM(amount), 0)
FROM wallet_histories
WHERE wallet_id = #{walletId}
  AND transaction_type = 'PAYMENT'
  AND status = 'SUCCESS'
  AND DATE_FORMAT(created_at, '%Y-%m') = #{yearMonth}

SELECT COUNT(*)
FROM wallet_histories
WHERE wallet_id = #{walletId}
  AND transaction_type = 'PAYMENT'
  AND status = 'SUCCESS'
  AND DATE_FORMAT(created_at, '%Y-%m') = #{yearMonth}

SELECT DATE_FORMAT(created_at, '%Y-%m') AS year_month, SUM(amount) AS amount FROM wallet_histories WHERE wallet_id = #{walletId} AND transaction_type = 'PAYMENT' AND status = 'SUCCESS' AND DATE_FORMAT(created_at, '%Y-%m') IN
#{ym}
GROUP BY DATE_FORMAT(created_at, '%Y-%m')

SELECT IFNULL(SUM(pbh.amount), 0)
FROM piggy_bank_histories pbh
         JOIN piggy_banks pb ON pb.id = pbh.piggy_bank_id
WHERE pb.wallet_id = #{walletId}
  AND pbh.history_type = 'DEPOSIT'
  AND DATE_FORMAT(pbh.created_at, '%Y-%m') = #{yearMonth}

SELECT DATE_FORMAT(MIN(created_at), '%Y-%m')
FROM wallet_histories
WHERE wallet_id = #{walletId}
